from unittest.mock import Mock

def load_topic(fetch, key):
    try:
        topic = fetch(key)
    except KeyError:
        return "Missing"
    return "Topic: " + topic

def check_fetch(key, missing=False):
    fake = Mock(side_effect=KeyError("absent")) if missing else Mock(return_value="Maps")
    result = load_topic(fake, key)
    fake.assert_called_once_with(key)
    return result

def check_other_error():
    fake = Mock(side_effect=RuntimeError("offline"))
    try:
        load_topic(fake, "id")
    except RuntimeError:
        fake.assert_called_once_with("id")
        return True
    return False
